34	    public PasswordEntryDialog(Context context, Mode newMode, boolean blockAccessibility, PasswordEnteredCallback newCallback) {
35	        super(context, Tools.getThemeResource(context, R.attr.dialogTheme));
36	
37	        setTitle(R.string.dialog_title_enter_password);
38	        setContentView(R.layout.dialog_password_entry);
39	
40	        TextInputLayout passwordLayout = findViewById(R.id.passwordInputLayout);
41	        passwordInput = findViewById(R.id.passwordInput);
42	        passwordConfirm = findViewById(R.id.passwordConfirm);
43	
44	        if (blockAccessibility) {
45	            passwordLayout.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO_HIDE_DESCENDANTS);
46	            passwordConfirm.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO);
47	        }
48	
49	        okButton = findViewById(R.id.buttonOk);
50	        Button cancelButton = findViewById(R.id.buttonCancel);
51	
52	        okButton.setOnClickListener(this);
53	        cancelButton.setOnClickListener(this);
54	
55	        this.callback = newCallback;
56	
57	        this.dialogMode = newMode;
58	
59	        if (this.dialogMode == Mode.UPDATE) {
60	            passwordConfirm.setVisibility(View.VISIBLE);
61	            passwordInput.addTextChangedListener(this);
62	            passwordConfirm.addTextChangedListener(this);
63	        } else if (this.dialogMode == Mode.ENTER) {
64	            passwordConfirm.setVisibility(View.GONE);
65	        }
66	    }
67	
68	    // TextWatcher
69	    public void onTextChanged(CharSequence s, int start, int before, int count) {
70	        if (TextUtils.equals(passwordInput.getEditableText(), passwordConfirm.getEditableText()))
71	            okButton.setEnabled(true);
72	        else
73	            okButton.setEnabled(false);
74	    }
75	
76	    public void afterTextChanged(Editable s) {}
77	    public void beforeTextChanged(CharSequence s, int start, int count, int after) {}
78	
79	    // View.OnClickListener
80	    public void onClick(View view)  {
81	        if (view.getId() == R.id.buttonOk) {
82	            if (callback != null)
83	                callback.onPasswordEntered(passwordInput.getText().toString());
84	        }
85	
86	        dismiss();
87	    }
88	}
