    /**
     * Makes the password visibility toggle of a {@link TextInputLayout} apply to the confirmation
     * field as well, so both fields always show the same (hidden or visible) content.
     *
     * The default toggle of the TextInputLayout only affects its own EditText, which means the
     * confirmation field would stay obscured while the password field is shown.
     *
     * @param passwordLayout  the layout containing the password field and the visibility toggle
     * @param passwordInput   the password input field (child of the passwordLayout)
     * @param passwordConfirm the confirmation field, which should follow the password field
     */
    public static void setupPasswordVisibilityToggle(final TextInputLayout passwordLayout, final EditText passwordInput, final EditText passwordConfirm) {
        if (passwordLayout == null || passwordInput == null || passwordConfirm == null)
            return;

        // Make sure both fields start out in the same state
        setPasswordVisible(passwordConfirm, isPasswordVisible(passwordInput));

        passwordLayout.setEndIconOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View view) {
                boolean showPassword = ! isPasswordVisible(passwordInput);

                setPasswordVisible(passwordInput, showPassword);
                setPasswordVisible(passwordConfirm, showPassword);
            }
        });
    }

    /** Checks if the content of the given input field is currently readable. */
    public static boolean isPasswordVisible(EditText editText) {
        return ! (editText.getTransformationMethod() instanceof PasswordTransformationMethod);
    }

    /** Shows or hides the content of the given input field, preserving the current selection. */
    public static void setPasswordVisible(EditText editText, boolean visible) {
        if (editText == null || isPasswordVisible(editText) == visible)
            return;

        int selectionStart = editText.getSelectionStart();
        int selectionEnd = editText.getSelectionEnd();

        editText.setTransformationMethod(visible ? null : new PasswordTransformationMethod());

        if (selectionStart >= 0 && selectionEnd >= 0)
            editText.setSelection(selectionStart, selectionEnd);
    }
